package com.dramastudio.service;
import com.dramastudio.engine.*; import com.dramastudio.entity.*; import com.dramastudio.repository.*; import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import java.time.Instant; import java.util.*; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
@Service public class RunService {
 private final WorkflowService workflow;private final WorkflowRunRepository runs;private final NodeRunRepository nodeRuns;private final ObjectMapper json;private final DagValidator dag;private final WorkflowExecutor executor;
 public RunService(WorkflowService w,WorkflowRunRepository r,NodeRunRepository n,ObjectMapper j,DagValidator d,WorkflowExecutor e){workflow=w;runs=r;nodeRuns=n;json=j;dag=d;executor=e;}
 public WorkflowRun start(String workflowId,List<String> targets,String user){WorkflowVersion v=workflow.latestOrPublish(workflowId,user);Map<String,Object> snapshot=parse(v.snapshotJson);var issues=dag.validate(snapshot);if(!issues.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,issues.get(0).message());Workflow w=workflow.owned(workflowId,user);WorkflowRun run=new WorkflowRun();run.workflowId=workflowId;run.workflowVersionId=v.id;run.projectId=w.projectId;run.targetNodeIdsJson=write(targets);run.status="QUEUED";run.inputSnapshotJson="{}";run.createdBy=user;runs.saveAndFlush(run);executor.execute(run.id,snapshot,dag.topological(snapshot));return run;}
 public WorkflowRun get(String id,String user){WorkflowRun r=runs.findById(id).orElseThrow();workflow.owned(r.workflowId,user);return r;}public List<NodeRun> nodeRuns(String id,String user){get(id,user);return nodeRuns.findByWorkflowRunIdOrderByCreatedAt(id);}public List<WorkflowRun> list(String user){return runs.findAllByOrderByCreatedAtDesc().stream().filter(r->{try{workflow.owned(r.workflowId,user);return true;}catch(Exception e){return false;}}).toList();}
 @Transactional public void cancel(String id,String user){WorkflowRun r=get(id,user);r.status="CANCELED";r.finishedAt=Instant.now().toString();runs.save(r);for(NodeRun n:nodeRuns.findByWorkflowRunIdOrderByCreatedAt(id))if(List.of("PENDING","QUEUED","RUNNING").contains(n.status)){n.status="CANCELED";nodeRuns.save(n);}}
 private Map<String,Object> parse(String s){try{return json.readValue(s,new TypeReference<>(){});}catch(Exception e){throw new IllegalArgumentException(e);}}private String write(Object o){try{return json.writeValueAsString(o==null?List.of():o);}catch(Exception e){throw new IllegalArgumentException(e);}}
}
